var ctx = document.getElementById('c').getContext('2d');
var x = 30, y = 50, dx = 3, dy = 2;
function frame() {
  ctx.clearRect(0, 0, 320, 160);
  ctx.fillStyle = '#90e0ef'; ctx.fillRect(10, 10, 80, 40);
  ctx.strokeStyle = '#e34c26'; ctx.lineWidth = 3; ctx.strokeRect(100, 10, 80, 40);
  ctx.fillStyle = '#222'; ctx.font = '16px sans-serif'; ctx.fillText('Canvas!', 200, 35);
  ctx.beginPath(); ctx.arc(x, y + 40, 16, 0, Math.PI * 2); ctx.fillStyle = '#e34c26'; ctx.fill();
  x += dx; y += dy;
  if (x < 16 || x > 304) dx = -dx;
  if (y < 10 || y > 94) dy = -dy;
  requestAnimationFrame(frame);
}
frame();

