class UserBadge extends HTMLElement {
  static get observedAttributes() { return ['name', 'role-title']; }
  connectedCallback() {
    this.root = this.attachShadow({ mode: 'open' });
    this.root.innerHTML = '<style>.b{display:inline-flex;gap:8px;align-items:center;background:#fff4f0;border:1px solid #e34c26;border-radius:999px;padding:4px 12px;margin:4px;font-family:sans-serif}.av{background:#e34c26;color:#fff;border-radius:50%;width:26px;height:26px;display:grid;place-items:center}</style><span class="b"><span class="av"></span><span class="n"></span><small class="r"></small></span>';
    this.render();
  }
  attributeChangedCallback() { if (this.root) this.render(); }
  render() {
    var n = this.getAttribute('name') || '?';
    this.root.querySelector('.av').textContent = n.charAt(0);
    this.root.querySelector('.n').textContent = n;
    this.root.querySelector('.r').textContent = this.getAttribute('role-title') || '';
  }
}
customElements.define('user-badge', UserBadge);
